/**
 * Un angle par montant et par langue (RECETTE §6.2) : le seuil réel propre à chaque salaire.
 * Les montants viennent du moteur, jamais écrits à la main.
 */
import { compute, employerCost, doublePecule, yearEndBonus } from './engine/be';
import P from '../data/params-2026.json';
import { fmt } from './format';

export interface Angle { title: string; description: string; h1: string; h2: string; p: string; h2b: string; p2: string; faqs: Array<{ q: string; a: string }> }
type Lang = 'fr' | 'nl';
const B = P.bonus.employe;

export function monthlyAngle(g: number, lang: Lang): Angle {
  const f = fmt(lang); const $ = (v: number, d = 2) => f.money(v, d); const pct = f.pct;
  const r = compute({ gross: g });
  const up = compute({ gross: g + 100 });
  const marg = 1 - (up.net - r.net) / 100;
  const cs = compute({ gross: g, situation: 'conjoint_sans' });
  const k2 = compute({ gross: g, children: 2 });
  const ec = employerCost(g);
  const dp = doublePecule({ gross: g });
  const yb = yearEndBonus({ gross: g });
  const h1 = lang === 'fr' ? `Salaire brut de ${$(g, 0)} : combien en net en 2026 ?` : `Brutoloon van ${$(g, 0)}: hoeveel netto in 2026?`;
  const F: Record<number, () => Angle> = {
    2200: () => lang === 'fr' ? ({ h1,
      title: `2 200 € brut en net 2026 : proche du salaire minimum`, description: `2 200 € brut par mois donnent ${$(r.net)} net en 2026 pour un employé isolé. Le bonus à l’emploi efface presque toute la cotisation ONSS à ce niveau.`,
      h2: 'Juste au-dessus du salaire minimum',
      p: `Un salaire brut de ${$(g, 0)} dépasse de peu le revenu minimum mensuel moyen garanti, ${$(P.rmmmg.amount)} depuis le 1er avril 2026. À ce niveau, la cotisation personnelle ONSS de 13,07 %, ${$(r.onss)}, est entièrement compensée par le bonus à l’emploi social : le volet A de ${$(r.bonusA)} et le volet B de ${$(r.bonusB)}, écrêté pour ne pas dépasser la cotisation due. Il ne reste donc que ${$(r.onssNet)} de cotisations. Le précompte professionnel calculé selon la formule-clé est ensuite réduit du bonus à l’emploi fiscal, ${$(r.fiscalBonus)}, et tombe à ${$(r.pp)}. Avec la cotisation spéciale de sécurité sociale de ${$(r.csss)}, le salaire net atteint ${$(r.net)}, soit ${pct(r.net / g)} du brut. C’est le niveau de salaire où l’écart entre brut et net est le plus faible en Belgique, précisément parce que les deux bonus visent les bas salaires.`,
      h2b: 'Ce que coûte une augmentation',
      p2: `Les bonus diminuent à mesure que le salaire augmente. Une hausse de ${$(100, 0)} brut ne rapporte ici que ${$(up.net - r.net)} net, car l’employé perd une partie du volet B du bonus à l’emploi en plus du précompte supplémentaire.`,
      faqs: [
        { q: 'Combien fait 2 200 € brut en net ?', a: `Environ ${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant, après ${$(r.onssNet)} d’ONSS, ${$(r.pp)} de précompte professionnel et ${$(r.csss)} de cotisation spéciale. Avec un conjoint sans revenus, le net monte à ${$(cs.net)}, car le quotient conjugal annule presque tout le précompte.` },
        { q: 'Quel est le salaire minimum brut depuis avril 2026 ?', a: `Le revenu minimum mensuel moyen garanti est de ${$(P.rmmmg.amount)} brut par mois depuis le 1er avril 2026 pour un temps plein de 18 ans et plus, après une hausse de 35 € prévue par l’accord interprofessionnel. Des minimums sectoriels plus élevés s’appliquent souvent via les commissions paritaires.` },
        { q: 'Pourquoi l’ONSS est-il presque nul à 2 200 € ?', a: `Parce que le bonus à l’emploi social réduit la cotisation personnelle de 13,07 % pour les bas salaires. À ${$(g, 0)}, les volets A et B totalisent ${$(r.bonus)}, soit toute la cotisation. Le travailleur conserve pourtant tous ses droits à la sécurité sociale : le bonus réduit la cotisation, pas la protection.` },
      ] }) : ({ h1,
      title: `2 200 euro bruto netto 2026: net boven het minimumloon`, description: `2 200 euro bruto per maand geeft ${$(r.net)} netto in 2026 voor een alleenstaande bediende. De werkbonus neemt op dit niveau bijna alle RSZ weg.`,
      h2: 'Net boven het minimumloon',
      p: `Een brutoloon van ${$(g, 0)} ligt net boven het gewaarborgd gemiddeld minimum maandinkomen, dat sinds 1 april 2026 ${$(P.rmmmg.amount)} bedraagt. Op dit niveau wordt de persoonlijke RSZ-bijdrage van 13,07 %, ${$(r.onss)}, volledig gecompenseerd door de sociale werkbonus: luik A van ${$(r.bonusA)} en luik B van ${$(r.bonusB)}, afgetopt zodat de bonus de verschuldigde bijdrage niet overschrijdt. Er blijft dus ${$(r.onssNet)} aan bijdragen over. De bedrijfsvoorheffing volgens de sleutelformule wordt daarna verminderd met de fiscale werkbonus, ${$(r.fiscalBonus)}, en zakt tot ${$(r.pp)}. Met de bijzondere bijdrage voor de sociale zekerheid van ${$(r.csss)} komt het nettoloon op ${$(r.net)}, of ${pct(r.net / g)} van het brutoloon. Op dit loonniveau is het verschil tussen bruto en netto in België het kleinst, net omdat beide bonussen op lage lonen gericht zijn.`,
      h2b: 'Wat een loonsverhoging kost',
      p2: `De bonussen dalen naarmate het loon stijgt. Een verhoging van ${$(100, 0)} bruto levert hier maar ${$(up.net - r.net)} netto op, omdat de bediende een deel van luik B van de werkbonus verliest bovenop de extra voorheffing.`,
      faqs: [
        { q: 'Hoeveel is 2 200 euro bruto in netto?', a: `Ongeveer ${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen, na ${$(r.onssNet)} RSZ, ${$(r.pp)} bedrijfsvoorheffing en ${$(r.csss)} bijzondere bijdrage. Met een partner zonder inkomen stijgt het nettoloon tot ${$(cs.net)}, omdat het huwelijksquotiënt bijna alle voorheffing wegneemt.` },
        { q: 'Hoeveel is het bruto minimumloon sinds april 2026?', a: `Het gewaarborgd gemiddeld minimum maandinkomen bedraagt sinds 1 april 2026 ${$(P.rmmmg.amount)} bruto per maand voor een voltijdse werknemer van 18 jaar of ouder, na een verhoging met 35 euro uit het interprofessioneel akkoord. Sectorale minimumlonen liggen vaak hoger. Het bedrag geldt voor alle werknemers van 18 jaar of ouder.` },
        { q: 'Waarom is de RSZ bijna nul bij 2 200 euro?', a: `Omdat de sociale werkbonus de persoonlijke bijdrage van 13,07 % voor lage lonen vermindert. Bij ${$(g, 0)} bedragen luik A en luik B samen ${$(r.bonus)}, dus de volledige bijdrage. De werknemer behoudt toch al zijn rechten in de sociale zekerheid: de bonus verlaagt de bijdrage, niet de bescherming.` },
      ] }),
    2500: () => lang === 'fr' ? ({ h1,
      title: `2 500 € brut en net 2026 : bonus à l’emploi en recul`, description: `2 500 € brut par mois donnent ${$(r.net)} net en 2026 pour un employé isolé. Le volet B du bonus à l’emploi diminue déjà au-delà de ${$(B.b_from)}.`,
      h2: 'Le volet B commence à diminuer',
      p: `À ${$(g, 0)} brut, vous êtes dans la zone où le volet B du bonus à l’emploi, réservé aux très bas salaires, décroît. Il vaut ${$(B.b_max)} jusqu’à un salaire de ${$(B.b_from)}, puis diminue de ${f.dec(B.b_slope * 100, 2)} cents par euro de salaire supplémentaire jusqu’à disparaître à ${$(B.b_to)}. Ici, il reste ${$(r.bonusB)}, auquel s’ajoute le volet A complet de ${$(r.bonusA)}. La cotisation ONSS de ${$(r.onss)} est ainsi ramenée à ${$(r.onssNet)}. Sur la rémunération imposable de ${$(r.imposable)}, le précompte professionnel est de ${$(r.pp)} après la réduction fiscale de ${$(r.fiscalBonus)} liée au bonus. Avec ${$(r.csss)} de cotisation spéciale, le net est de ${$(r.net)}. Un salaire de 2 500 € brut est courant pour un premier emploi ou dans les secteurs aux barèmes modestes, et c’est à ce niveau que le bonus à l’emploi pèse le plus dans la différence entre deux salaires.`,
      h2b: 'Avec des enfants',
      p2: `Avec deux enfants à charge, la réduction pour enfants de la formule-clé fait passer le net à ${$(k2.net)}. Avec un conjoint sans revenus, il atteint ${$(cs.net)}.`,
      faqs: [
        { q: 'Combien fait 2 500 € brut en net en 2026 ?', a: `Environ ${$(r.net)} par mois pour un employé isolé sans enfant, soit ${pct(r.net / g)} du brut. Le calcul inclut ${$(r.onssNet)} d’ONSS après bonus à l’emploi, ${$(r.pp)} de précompte professionnel et ${$(r.csss)} de cotisation spéciale de sécurité sociale. Le montant exact dépend de votre commission paritaire.` },
        { q: 'Combien vaut le bonus à l’emploi à 2 500 € ?', a: `${$(r.bonus)} par mois : ${$(r.bonusA)} au titre du volet A et ${$(r.bonusB)} au titre du volet B. Il réduit la cotisation ONSS personnelle. Le bonus fiscal qui l’accompagne diminue en plus le précompte de ${$(r.fiscalBonus)}. Les deux volets sont calculés sur le salaire de référence à temps plein.` },
        { q: 'Quel est le coût employeur de 2 500 € brut ?', a: `Environ ${$(ec.monthly)} par mois avec les cotisations patronales de base et la modération salariale, 25 % au total pour un employeur du secteur privé. Sur un an, avec treizième mois et double pécule, le coût atteint ${$(ec.annual, 0)}, hors réduction structurelle et assurances.` },
      ] }) : ({ h1,
      title: `2 500 euro bruto netto 2026: werkbonus neemt af`, description: `2 500 euro bruto per maand geeft ${$(r.net)} netto in 2026 voor een alleenstaande bediende. Luik B van de werkbonus daalt al boven ${$(B.b_from)}.`,
      h2: 'Luik B begint te dalen',
      p: `Bij ${$(g, 0)} bruto zit je in de zone waar luik B van de werkbonus, bedoeld voor de zeer lage lonen, afneemt. Het bedraagt ${$(B.b_max)} tot een loon van ${$(B.b_from)} en daalt daarna met ${f.dec(B.b_slope * 100, 2)} cent per euro extra loon, tot het verdwijnt bij ${$(B.b_to)}. Hier blijft ${$(r.bonusB)} over, bovenop het volledige luik A van ${$(r.bonusA)}. De RSZ-bijdrage van ${$(r.onss)} daalt zo tot ${$(r.onssNet)}. Op het belastbaar loon van ${$(r.imposable)} bedraagt de bedrijfsvoorheffing ${$(r.pp)} na de fiscale vermindering van ${$(r.fiscalBonus)} die bij de werkbonus hoort. Met ${$(r.csss)} bijzondere bijdrage is het nettoloon ${$(r.net)}. Een brutoloon van 2 500 euro is gebruikelijk voor een eerste job of in sectoren met bescheiden barema’s, en op dit niveau weegt de werkbonus het zwaarst in het verschil tussen twee lonen.`,
      h2b: 'Met kinderen',
      p2: `Met twee kinderen ten laste brengt de vermindering voor kinderen uit de sleutelformule het nettoloon op ${$(k2.net)}. Met een partner zonder inkomen wordt het ${$(cs.net)}.`,
      faqs: [
        { q: 'Hoeveel is 2 500 euro bruto netto in 2026?', a: `Ongeveer ${$(r.net)} per maand voor een alleenstaande bediende zonder kinderen, of ${pct(r.net / g)} van het brutoloon. De berekening omvat ${$(r.onssNet)} RSZ na werkbonus, ${$(r.pp)} bedrijfsvoorheffing en ${$(r.csss)} bijzondere bijdrage voor de sociale zekerheid. Het exacte bedrag hangt af van je paritair comité.` },
        { q: 'Hoeveel bedraagt de werkbonus bij 2 500 euro?', a: `${$(r.bonus)} per maand: ${$(r.bonusA)} uit luik A en ${$(r.bonusB)} uit luik B. De bonus verlaagt de persoonlijke RSZ-bijdrage. De fiscale werkbonus die ermee samenhangt, verlaagt de voorheffing bovendien met ${$(r.fiscalBonus)}. Beide luiken worden berekend op het refertemaandloon voor een voltijdse job.` },
        { q: 'Wat is de werkgeverskost van 2 500 euro bruto?', a: `Ongeveer ${$(ec.monthly)} per maand met de basiswerkgeversbijdragen en de loonmatiging, samen 25 % voor een werkgever uit de privésector. Op jaarbasis, met eindejaarspremie en dubbel vakantiegeld, loopt de kost op tot ${$(ec.annual, 0)}, zonder structurele vermindering en verzekeringen. Het gaat om een schatting.` },
      ] }),
    2800: () => lang === 'fr' ? ({ h1,
      title: `2 800 € brut en net 2026 : le piège des augmentations`, description: `2 800 € brut donnent ${$(r.net)} net en 2026. Entre 2 300 et 3 400 € brut, la perte du bonus à l’emploi rend chaque augmentation peu rentable en net.`,
      h2: 'Une zone où l’augmentation rapporte peu',
      p: `Entre ${$(B.b_from)} et ${$(B.a_to)} brut, chaque euro d’augmentation fait perdre une partie du bonus à l’emploi, en plus du précompte supplémentaire. À ${$(g, 0)}, le volet B n’est plus que de ${$(r.bonusB)} et le volet A reste de ${$(r.bonusA)}. Résultat : une augmentation de ${$(100, 0)} brut ne rapporte que ${$(up.net - r.net)} net, ce qui correspond à un taux marginal de ${pct(marg)}. C’est plus que pour un salaire de 5 000 €. Ce paradoxe s’explique par la conception du bonus, qui cible les bas salaires et se retire progressivement. Au total, le salaire de ${$(g, 0)} brut laisse ${$(r.net)} net, après ${$(r.onssNet)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale. Pour négocier, il est utile de raisonner en net : un avantage non soumis à cotisations, comme des chèques-repas, peut valoir davantage qu’une petite augmentation brute dans cette zone.`,
      h2b: 'Et pour l’employeur',
      p2: `L’employeur paie environ ${$(ec.monthly)} par mois pour ce salaire. Pour lui, 100 € brut de plus coûtent 125 €, alors que l’employé n’en reçoit que ${$(up.net - r.net)}.`,
      faqs: [
        { q: 'Combien fait 2 800 € brut en net ?', a: `Environ ${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant. Le bonus à l’emploi de ${$(r.bonus)} réduit encore l’ONSS, et le précompte professionnel est de ${$(r.pp)} après réduction fiscale. Avec deux enfants à charge, le net est de ${$(k2.net)}.` },
        { q: 'Pourquoi une augmentation rapporte-t-elle si peu vers 2 800 € ?', a: `Parce que le bonus à l’emploi diminue quand le salaire augmente. À ce niveau, 100 € brut supplémentaires ne rapportent que ${$(up.net - r.net)} net : l’employé paie plus de précompte et perd en même temps une partie du volet B du bonus. L’effet disparaît au-delà de ${$(B.a_to)} brut.` },
        { q: 'Les chèques-repas sont-ils plus intéressants qu’une augmentation ?', a: 'Dans cette zone de salaire, souvent. Les chèques-repas, dans les limites légales, ne sont soumis ni à l’ONSS ni au précompte, alors qu’une augmentation brute subit la perte du bonus à l’emploi et le précompte. Leur usage est toutefois limité à l’alimentation et leur valeur plafonnée.' },
      ] }) : ({ h1,
      title: `2 800 euro bruto netto 2026: de valkuil van opslag`, description: `2 800 euro bruto geeft ${$(r.net)} netto in 2026. Tussen 2 300 en 3 400 euro bruto maakt het verlies van de werkbonus elke opslag weinig lonend.`,
      h2: 'Een zone waar opslag weinig oplevert',
      p: `Tussen ${$(B.b_from)} en ${$(B.a_to)} bruto kost elke euro opslag een deel van de werkbonus, bovenop de extra voorheffing. Bij ${$(g, 0)} is luik B nog maar ${$(r.bonusB)} en blijft luik A ${$(r.bonusA)}. Gevolg: een opslag van ${$(100, 0)} bruto levert slechts ${$(up.net - r.net)} netto op, wat overeenkomt met een marginaal tarief van ${pct(marg)}. Dat is meer dan bij een loon van 5 000 euro. Die paradox volgt uit de opzet van de werkbonus, die op lage lonen mikt en geleidelijk wegvalt. In totaal laat een brutoloon van ${$(g, 0)} ${$(r.net)} netto over, na ${$(r.onssNet)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage. Bij onderhandelingen loont het om in netto te denken: een voordeel zonder bijdragen, zoals maaltijdcheques, kan in deze zone meer waard zijn dan een kleine brutoverhoging.`,
      h2b: 'En voor de werkgever',
      p2: `De werkgever betaalt ongeveer ${$(ec.monthly)} per maand voor dit loon. Voor hem kost 100 euro bruto meer 125 euro, terwijl de bediende er maar ${$(up.net - r.net)} van ontvangt.`,
      faqs: [
        { q: 'Hoeveel is 2 800 euro bruto netto?', a: `Ongeveer ${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen. De werkbonus van ${$(r.bonus)} verlaagt nog de RSZ, en de bedrijfsvoorheffing bedraagt ${$(r.pp)} na fiscale vermindering. Met twee kinderen ten laste is het nettoloon ${$(k2.net)}.` },
        { q: 'Waarom levert opslag rond 2 800 euro zo weinig op?', a: `Omdat de werkbonus daalt als het loon stijgt. Op dit niveau levert 100 euro bruto extra maar ${$(up.net - r.net)} netto op: de bediende betaalt meer voorheffing en verliest tegelijk een deel van luik B. Het effect verdwijnt boven ${$(B.a_to)} bruto. Het is een tijdelijk effect van de afbouw.` },
        { q: 'Zijn maaltijdcheques interessanter dan opslag?', a: 'In deze loonzone vaak wel. Maaltijdcheques binnen de wettelijke grenzen zijn niet onderworpen aan RSZ of bedrijfsvoorheffing, terwijl een brutoverhoging het verlies van de werkbonus en voorheffing ondergaat. Ze zijn wel beperkt tot voeding en hun waarde is begrensd. Het is dus een afweging.' },
      ] }),
    3000: () => lang === 'fr' ? ({ h1,
      title: `3 000 € brut en net 2026 : seul le volet A demeure`, description: `3 000 € brut donnent ${$(r.net)} net en 2026. Au-delà de ${$(B.b_to)}, le volet B du bonus à l’emploi a disparu et seul le volet A réduit encore l’ONSS.`,
      h2: 'Plus de volet B, un volet A réduit',
      p: `À ${$(g, 0)} brut, le volet B du bonus à l’emploi a disparu : il s’arrête à ${$(B.b_to)}. Le volet A, qui vaut ${$(B.a_max)} jusqu’à ce même seuil, diminue ensuite de ${f.dec(B.a_slope * 100, 2)} cents par euro et vaut ici ${$(r.bonusA)}. La cotisation ONSS passe donc de ${$(r.onss)} à ${$(r.onssNet)}. Le précompte professionnel est de ${$(r.pp)}, après une réduction fiscale de ${$(r.fiscalBonus)} égale à ${f.dec(P.bonus.fiscal_a * 100, 2)} % du volet A. La cotisation spéciale de sécurité sociale s’élève à ${$(r.csss)}. Le net mensuel atteint ${$(r.net)}, soit ${pct(r.net / g)} du brut. Un salaire de 3 000 € brut est un repère fréquent dans les offres d’emploi pour des profils avec quelques années d’expérience ; c’est aussi le dernier palier où le bonus à l’emploi joue encore un rôle notable dans le net.`,
      h2b: 'Situation familiale',
      p2: `Avec un conjoint sans revenus professionnels, le net passe à ${$(cs.net)} grâce au quotient conjugal. Avec deux enfants à charge, il est de ${$(k2.net)}.`,
      faqs: [
        { q: 'Combien fait 3 000 € brut en net ?', a: `Environ ${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant, après ${$(r.onssNet)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale. Pour un ouvrier, dont l’ONSS est calculé sur 108 % du brut, le net est de ${$(compute({ gross: g, status: 'ouvrier' }).net)}.` },
        { q: 'Jusqu’à quel salaire a-t-on droit au bonus à l’emploi ?', a: `Jusqu’à ${$(B.a_to)} brut par mois pour un employé à temps plein, depuis le 1er septembre 2026. Le volet B s’arrête à ${$(B.b_to)} et le volet A diminue progressivement entre ${$(B.a_from)} et ${$(B.a_to)}. Pour un temps partiel, le montant est proratisé.` },
        { q: 'Combien coûte un salaire de 3 000 € brut à l’employeur ?', a: `Environ ${$(ec.monthly)} par mois, avec 25 % de cotisations patronales de base et de modération salariale. Sur un an, en comptant treizième mois et double pécule de vacances, le coût dépasse ${$(ec.annual, 0)}, avant réductions structurelles et hors assurance accident du travail.` },
      ] }) : ({ h1,
      title: `3 000 euro bruto netto 2026: enkel luik A blijft over`, description: `3 000 euro bruto geeft ${$(r.net)} netto in 2026. Boven ${$(B.b_to)} is luik B van de werkbonus verdwenen en verlaagt enkel luik A nog de RSZ.`,
      h2: 'Geen luik B meer, een kleiner luik A',
      p: `Bij ${$(g, 0)} bruto is luik B van de werkbonus verdwenen: het stopt bij ${$(B.b_to)}. Luik A, dat ${$(B.a_max)} bedraagt tot diezelfde grens, daalt daarna met ${f.dec(B.a_slope * 100, 2)} cent per euro en bedraagt hier ${$(r.bonusA)}. De RSZ-bijdrage gaat zo van ${$(r.onss)} naar ${$(r.onssNet)}. De bedrijfsvoorheffing bedraagt ${$(r.pp)}, na een fiscale vermindering van ${$(r.fiscalBonus)}, gelijk aan ${f.dec(P.bonus.fiscal_a * 100, 2)} % van luik A. De bijzondere bijdrage voor de sociale zekerheid is ${$(r.csss)}. Het netto maandloon bedraagt ${$(r.net)}, of ${pct(r.net / g)} van het brutoloon. Een brutoloon van 3 000 euro is een vaak gebruikt ijkpunt in vacatures voor profielen met enkele jaren ervaring; het is ook de laatste trede waarop de werkbonus nog een merkbare rol speelt in het nettoloon. Wie een aanbod vergelijkt, kijkt dus best naar het netto.`,
      h2b: 'Gezinssituatie',
      p2: `Met een partner zonder beroepsinkomen stijgt het nettoloon tot ${$(cs.net)} dankzij het huwelijksquotiënt. Met twee kinderen ten laste is het ${$(k2.net)}.`,
      faqs: [
        { q: 'Hoeveel is 3 000 euro bruto netto?', a: `Ongeveer ${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen, na ${$(r.onssNet)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage. Voor een arbeider, bij wie de RSZ op 108 % van het brutoloon wordt berekend, is het nettoloon ${$(compute({ gross: g, status: 'ouvrier' }).net)}.` },
        { q: 'Tot welk loon heb je recht op de werkbonus?', a: `Tot ${$(B.a_to)} bruto per maand voor een voltijdse bediende, sinds 1 september 2026. Luik B stopt bij ${$(B.b_to)} en luik A daalt geleidelijk tussen ${$(B.a_from)} en ${$(B.a_to)}. Voor een deeltijdse werknemer wordt het bedrag pro rata berekend. De grenzen worden met de lonen geïndexeerd.` },
        { q: 'Wat kost een brutoloon van 3 000 euro aan de werkgever?', a: `Ongeveer ${$(ec.monthly)} per maand, met 25 % basiswerkgeversbijdragen en loonmatiging. Op jaarbasis, met eindejaarspremie en dubbel vakantiegeld, loopt de kost op tot meer dan ${$(ec.annual, 0)}, vóór structurele verminderingen en zonder arbeidsongevallenverzekering. Het gaat om een raming voor een bediende.` },
      ] }),
    3200: () => lang === 'fr' ? ({ h1,
      title: `3 200 € brut en net 2026 : fin du bonus à l’emploi`, description: `3 200 € brut donnent ${$(r.net)} net en 2026. Le volet A du bonus à l’emploi s’éteint à ${$(B.a_to)} : il ne vaut plus que ${$(r.bonusA)} à ce salaire.`,
      h2: 'Les derniers euros de bonus',
      p: `Un salaire de ${$(g, 0)} brut se situe dans la dernière tranche où le bonus à l’emploi existe encore. Le volet A ne vaut plus que ${$(r.bonusA)} et disparaîtra complètement à ${$(B.a_to)}. L’ONSS personnel passe ainsi de ${$(r.onss)} à ${$(r.onssNet)}. Le précompte professionnel est de ${$(r.pp)}, réduit de ${$(r.fiscalBonus)} au titre du bonus fiscal. Avec ${$(r.csss)} de cotisation spéciale de sécurité sociale, le net est de ${$(r.net)}. Entre 3 200 et 3 400 € brut, le taux marginal reste élevé, ${pct(marg)} ici, car la perte des derniers euros de bonus s’ajoute au précompte. Au-delà de ${$(B.a_to)}, la différence entre deux salaires ne dépend plus que du précompte, de l’ONSS de 13,07 % et de la cotisation spéciale, et le taux marginal redescend légèrement avant de remonter avec les tranches du barème.`,
      h2b: 'Pour un ouvrier',
      p2: `Un ouvrier au même salaire brut paie l’ONSS sur 108 %, soit ${$(compute({ gross: g, status: 'ouvrier' }).onss)}, et reçoit un bonus plus élevé. Son net est de ${$(compute({ gross: g, status: 'ouvrier' }).net)}.`,
      faqs: [
        { q: 'Combien fait 3 200 € brut en net ?', a: `Environ ${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant. Le calcul comprend ${$(r.onssNet)} d’ONSS après un bonus à l’emploi de ${$(r.bonusA)}, ${$(r.pp)} de précompte professionnel et ${$(r.csss)} de cotisation spéciale de sécurité sociale.` },
        { q: 'Que se passe-t-il au-delà de 3 403 € brut ?', a: `Le bonus à l’emploi disparaît complètement. L’ONSS personnel est alors de 13,07 % du brut pour un employé, sans réduction, et le précompte n’est plus diminué du bonus fiscal. Le salaire net progresse ensuite plus régulièrement avec le brut. Le seuil est indexé avec les salaires.` },
        { q: 'Quel est le taux marginal à 3 200 € brut ?', a: `Environ ${pct(marg)} : sur 100 € brut de plus, l’employé ne garde que ${$(up.net - r.net)}. Ce taux élevé vient de la combinaison du précompte professionnel, de l’ONSS et de la perte des derniers euros du volet A du bonus à l’emploi.` },
      ] }) : ({ h1,
      title: `3 200 euro bruto netto 2026: einde van de werkbonus`, description: `3 200 euro bruto geeft ${$(r.net)} netto in 2026. Luik A van de werkbonus valt weg bij ${$(B.a_to)}: bij dit loon is het nog maar ${$(r.bonusA)} waard.`,
      h2: 'De laatste euro’s werkbonus',
      p: `Een brutoloon van ${$(g, 0)} ligt in de laatste schijf waarin de werkbonus nog bestaat. Luik A is nog maar ${$(r.bonusA)} waard en verdwijnt volledig bij ${$(B.a_to)}. De persoonlijke RSZ gaat zo van ${$(r.onss)} naar ${$(r.onssNet)}. De bedrijfsvoorheffing bedraagt ${$(r.pp)}, verminderd met ${$(r.fiscalBonus)} als fiscale werkbonus. Met ${$(r.csss)} bijzondere bijdrage voor de sociale zekerheid is het nettoloon ${$(r.net)}. Tussen 3 200 en 3 400 euro bruto blijft het marginale tarief hoog, hier ${pct(marg)}, omdat het verlies van de laatste euro’s werkbonus bij de voorheffing komt. Boven ${$(B.a_to)} hangt het verschil tussen twee lonen enkel nog af van de voorheffing, de RSZ van 13,07 % en de bijzondere bijdrage, en daalt het marginale tarief licht voor het met de schijven van het barema weer stijgt.`,
      h2b: 'Voor een arbeider',
      p2: `Een arbeider met hetzelfde brutoloon betaalt RSZ op 108 %, of ${$(compute({ gross: g, status: 'ouvrier' }).onss)}, en krijgt een hogere werkbonus. Zijn nettoloon is ${$(compute({ gross: g, status: 'ouvrier' }).net)}.`,
      faqs: [
        { q: 'Hoeveel is 3 200 euro bruto netto?', a: `Ongeveer ${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen. De berekening omvat ${$(r.onssNet)} RSZ na een werkbonus van ${$(r.bonusA)}, ${$(r.pp)} bedrijfsvoorheffing en ${$(r.csss)} bijzondere bijdrage voor de sociale zekerheid. Met twee kinderen is het nettoloon ${$(k2.net)}.` },
        { q: 'Wat gebeurt er boven 3 403 euro bruto?', a: 'De werkbonus verdwijnt volledig. De persoonlijke RSZ bedraagt dan 13,07 % van het brutoloon voor een bediende, zonder vermindering, en de voorheffing wordt niet meer verlaagd met de fiscale werkbonus. Het nettoloon stijgt daarna regelmatiger met het brutoloon. Voor arbeiders geldt dezelfde grens.' },
        { q: 'Wat is het marginale tarief bij 3 200 euro bruto?', a: `Ongeveer ${pct(marg)}: van 100 euro bruto extra houdt de bediende maar ${$(up.net - r.net)} over. Dat hoge tarief komt van de combinatie van bedrijfsvoorheffing, RSZ en het verlies van de laatste euro’s uit luik A van de werkbonus. Boven 3 404 euro daalt het weer.` },
      ] }),
    3500: () => lang === 'fr' ? ({ h1,
      title: `3 500 € brut en net 2026 : calcul complet, sans bonus`, description: `3 500 € brut donnent ${$(r.net)} net en 2026 pour un employé isolé. Plus de bonus à l’emploi : voici le calcul étape par étape selon la formule-clé.`,
      h2: 'Le calcul étape par étape',
      p: `À ${$(g, 0)} brut, le bonus à l’emploi ne joue plus, et le calcul suit la formule-clé sans détour. L’ONSS personnel de 13,07 % s’élève à ${$(r.onss)}, ce qui laisse une rémunération imposable de ${$(r.imposable)}. La formule-clé multiplie ce montant par douze, ${$(r.ppBase.annual)}, retire les frais professionnels forfaitaires plafonnés à ${$(P.pp.frais_max, 0)} et obtient un revenu net imposable de ${$(r.ppBase.net)}. Le barème donne un impôt de base, dont on déduit ${$(P.pp.quotite_reduction)} au titre de la quotité exemptée : l’impôt annuel est de ${$(r.ppBase.annualTax)}, soit ${$(r.pp)} de précompte par mois. S’y ajoute la cotisation spéciale de sécurité sociale, ${$(r.csss)}. Le salaire net est de ${$(r.net)}. Ce détail est exactement celui qu’applique un secrétariat social, et chaque ligne peut être comparée à votre fiche de paie.`,
      h2b: 'Coût pour l’employeur',
      p2: `L’employeur paie ${$(ec.monthly)} par mois et environ ${$(ec.annual, 0)} par an avec treizième mois et double pécule. Le salarié reçoit ${pct(r.net / ec.monthly)} du coût mensuel en net.`,
      faqs: [
        { q: 'Combien fait 3 500 € brut en net en 2026 ?', a: `${$(r.net)} net par mois pour un employé isolé sans enfant : ${$(r.onss)} d’ONSS, ${$(r.pp)} de précompte professionnel et ${$(r.csss)} de cotisation spéciale. Avec un conjoint sans revenus, ${$(cs.net)} ; avec deux enfants à charge, ${$(k2.net)}.` },
        { q: 'Comment la formule-clé calcule-t-elle le précompte ?', a: `Elle part du brut diminué de l’ONSS, l’annualise, retire les frais forfaitaires de 30 % plafonnés à ${$(P.pp.frais_max, 0)}, applique le barème de 26,75 % à 53,50 %, déduit la quotité exemptée et les réductions pour charges de famille, puis divise par douze. Le résultat inclut déjà 7 % de taxe communale.` },
        { q: 'Combien de précompte sur un salaire de 3 500 € ?', a: `${$(r.pp)} par mois pour un isolé sans enfant, soit ${pct(r.pp / r.imposable)} de la rémunération imposable. Ce n’est qu’une avance : l’impôt définitif est établi par l’avertissement-extrait de rôle, qui tient compte de votre taxe communale réelle et de vos déductions. Le montant est arrondi au cent à chaque étape.` },
      ] }) : ({ h1,
      title: `3 500 euro bruto netto 2026: volledige berekening`, description: `3 500 euro bruto geeft ${$(r.net)} netto in 2026 voor een alleenstaande bediende. Geen werkbonus meer: dit is de berekening stap voor stap met de sleutelformule.`,
      h2: 'De berekening stap voor stap',
      p: `Bij ${$(g, 0)} bruto speelt de werkbonus niet meer, en volgt de berekening rechtstreeks de sleutelformule. De persoonlijke RSZ van 13,07 % bedraagt ${$(r.onss)}, waardoor een belastbaar loon van ${$(r.imposable)} overblijft. De sleutelformule vermenigvuldigt dat bedrag met twaalf, ${$(r.ppBase.annual)}, trekt de forfaitaire beroepskosten af, begrensd op ${$(P.pp.frais_max, 0)}, en komt zo op een netto belastbaar inkomen van ${$(r.ppBase.net)}. Het barema geeft een basisbelasting waarvan ${$(P.pp.quotite_reduction)} wordt afgetrokken voor de belastingvrije som: de jaarbelasting bedraagt ${$(r.ppBase.annualTax)}, of ${$(r.pp)} voorheffing per maand. Daarbij komt de bijzondere bijdrage voor de sociale zekerheid, ${$(r.csss)}. Het nettoloon bedraagt ${$(r.net)}. Die opbouw is precies wat een sociaal secretariaat toepast, en elke lijn kan je vergelijken met je loonfiche. Zo zie je meteen waar een verschil vandaan komt.`,
      h2b: 'Kost voor de werkgever',
      p2: `De werkgever betaalt ${$(ec.monthly)} per maand en ongeveer ${$(ec.annual, 0)} per jaar met eindejaarspremie en dubbel vakantiegeld. De werknemer ontvangt ${pct(r.net / ec.monthly)} van de maandkost als nettoloon.`,
      faqs: [
        { q: 'Hoeveel is 3 500 euro bruto netto in 2026?', a: `${$(r.net)} netto per maand voor een alleenstaande bediende zonder kinderen: ${$(r.onss)} RSZ, ${$(r.pp)} bedrijfsvoorheffing en ${$(r.csss)} bijzondere bijdrage. Met een partner zonder inkomen ${$(cs.net)}; met twee kinderen ten laste ${$(k2.net)}. Het gaat om bedragen per maand.` },
        { q: 'Hoe berekent de sleutelformule de voorheffing?', a: `Ze vertrekt van het brutoloon min RSZ, rekent het om naar een jaarbedrag, trekt 30 % forfaitaire kosten af, begrensd op ${$(P.pp.frais_max, 0)}, past het barema van 26,75 % tot 53,50 % toe, trekt de belastingvrije som en de verminderingen voor gezinslasten af en deelt door twaalf. Het resultaat bevat al 7 % gemeentebelasting.` },
        { q: 'Hoeveel voorheffing op een loon van 3 500 euro?', a: `${$(r.pp)} per maand voor een alleenstaande zonder kinderen, of ${pct(r.pp / r.imposable)} van het belastbaar loon. Het is maar een voorschot: de definitieve belasting volgt uit het aanslagbiljet, dat rekening houdt met je werkelijke gemeentebelasting en je aftrekken. Het bedrag wordt bij elke stap op de cent afgerond.` },
      ] }),
    3800: () => lang === 'fr' ? ({ h1,
      title: `3 800 € brut en net 2026 : l’effet du quotient conjugal`, description: `3 800 € brut donnent ${$(r.net)} net pour un isolé en 2026, mais ${$(cs.net)} si le conjoint n’a pas de revenus : le quotient conjugal fait la différence.`,
      h2: 'Marié avec un conjoint sans revenus',
      p: `La formule-clé du précompte tient compte de la situation familiale. Lorsque le conjoint ou cohabitant légal n’a pas de revenus professionnels, elle lui attribue fictivement 30 % du revenu net imposable, au maximum ${$(P.pp.conjoint_max, 0)} par an. Chaque part est imposée séparément au barème progressif, ce qui fait baisser l’impôt. Pour un salaire de ${$(g, 0)} brut, le précompte passe de ${$(r.pp)} à ${$(cs.pp)}, et le net de ${$(r.net)} à ${$(cs.net)}, soit ${$(cs.net - r.net)} de plus chaque mois. La cotisation spéciale de sécurité sociale reste celle d’un ménage à un seul revenu, ${$(cs.csss)}. Si le conjoint a des revenus, même modestes, le quotient conjugal ne s’applique pas au précompte, et la cotisation spéciale peut être un peu plus élevée. Le calcul définitif se fait dans la déclaration commune, où le quotient conjugal est appliqué sur les revenus réels du ménage.`,
      h2b: 'Pour un isolé',
      p2: `Sans conjoint, le net est de ${$(r.net)} après ${$(r.onss)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale.`,
      faqs: [
        { q: 'Combien fait 3 800 € brut en net ?', a: `${$(r.net)} net par mois pour un employé isolé sans enfant en 2026. Avec un conjoint sans revenus professionnels, le net monte à ${$(cs.net)}. Avec deux enfants à charge, un isolé reçoit ${$(k2.net)}. Les montants incluent ONSS, précompte et cotisation spéciale.` },
        { q: 'Qu’est-ce que le quotient conjugal ?', a: `Un mécanisme qui attribue une partie des revenus d’un conjoint à l’autre conjoint sans revenus, pour l’imposer à un taux plus bas. Dans le précompte, la part attribuée est de 30 % du revenu net imposable, avec un maximum de ${$(P.pp.conjoint_max, 0)} par an.` },
        { q: 'Le quotient conjugal vaut-il pour les cohabitants de fait ?', a: 'Non. Il est réservé aux personnes mariées et aux cohabitants légaux, imposés ensemble. Les cohabitants de fait sont imposés chacun comme un isolé, même si l’un d’eux n’a pas de revenus. Le calculateur applique les règles de la formule-clé pour chaque situation.' },
      ] }) : ({ h1,
      title: `3 800 euro bruto netto 2026: effect huwelijksquotiënt`, description: `3 800 euro bruto geeft ${$(r.net)} netto voor een alleenstaande in 2026, maar ${$(cs.net)} met een partner zonder inkomen, dankzij het huwelijksquotiënt.`,
      h2: 'Gehuwd met een partner zonder inkomen',
      p: `De sleutelformule van de bedrijfsvoorheffing houdt rekening met de gezinssituatie. Heeft de echtgenoot of wettelijk samenwonende partner geen beroepsinkomen, dan kent ze hem fictief 30 % van het netto belastbaar inkomen toe, met een maximum van ${$(P.pp.conjoint_max, 0)} per jaar. Elk deel wordt apart belast volgens het progressieve barema, wat de belasting verlaagt. Bij een brutoloon van ${$(g, 0)} daalt de voorheffing van ${$(r.pp)} naar ${$(cs.pp)}, en stijgt het nettoloon van ${$(r.net)} naar ${$(cs.net)}, of ${$(cs.net - r.net)} meer per maand. De bijzondere bijdrage voor de sociale zekerheid blijft die van een gezin met één inkomen, ${$(cs.csss)}. Heeft de partner een inkomen, zelfs een bescheiden, dan geldt het huwelijksquotiënt niet in de voorheffing en kan de bijzondere bijdrage iets hoger liggen. De definitieve berekening gebeurt in de gemeenschappelijke aangifte, waar het huwelijksquotiënt op de werkelijke inkomens van het gezin wordt toegepast.`,
      h2b: 'Voor een alleenstaande',
      p2: `Zonder partner bedraagt het nettoloon ${$(r.net)} na ${$(r.onss)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage.`,
      faqs: [
        { q: 'Hoeveel is 3 800 euro bruto netto?', a: `${$(r.net)} netto per maand voor een alleenstaande bediende zonder kinderen in 2026. Met een partner zonder beroepsinkomen stijgt het nettoloon tot ${$(cs.net)}. Met twee kinderen ten laste ontvangt een alleenstaande ${$(k2.net)}. De bedragen omvatten RSZ, voorheffing en bijzondere bijdrage.` },
        { q: 'Wat is het huwelijksquotiënt?', a: `Een mechanisme dat een deel van het inkomen van de ene partner toekent aan de partner zonder inkomen, zodat het tegen een lager tarief wordt belast. In de voorheffing bedraagt het toegekende deel 30 % van het netto belastbaar inkomen, met een maximum van ${$(P.pp.conjoint_max, 0)} per jaar.` },
        { q: 'Geldt het huwelijksquotiënt voor feitelijk samenwonenden?', a: 'Nee. Het is voorbehouden aan gehuwden en wettelijk samenwonenden, die samen worden belast. Feitelijk samenwonenden worden elk als alleenstaande belast, ook als een van beiden geen inkomen heeft. De rekenmodule past voor elke situatie de regels van de sleutelformule toe. Het verschil kan groot zijn.' },
      ] }),
    4000: () => lang === 'fr' ? ({ h1,
      title: `4 000 € brut en net 2026 : réduction pour enfants`, description: `4 000 € brut donnent ${$(r.net)} net en 2026 sans enfant, et ${$(k2.net)} avec deux enfants à charge. Voici ce que valent les réductions pour enfants.`,
      h2: 'Ce que valent les enfants à charge',
      p: `La formule-clé réduit l’impôt annuel d’un montant fixe selon le nombre d’enfants à charge : ${$(P.pp.enfants[1], 0)} pour un enfant, ${$(P.pp.enfants[2], 0)} pour deux, ${$(P.pp.enfants[3], 0)} pour trois et ${$(P.pp.enfants[4], 0)} pour quatre. Un enfant handicapé compte pour deux. Sur un salaire de ${$(g, 0)} brut, deux enfants font baisser le précompte de ${$(r.pp)} à ${$(k2.pp)} par mois, et le net passe de ${$(r.net)} à ${$(k2.net)}. Un parent isolé bénéficie en plus de ${$(P.pp.parent_isole, 0)} par an de réduction supplémentaire : son net atteint ${$(compute({ gross: g, children: 2, parentIsole: true }).net)}. Ces réductions sont annuelles et divisées par douze dans le précompte. Lorsque les deux parents travaillent, elles sont accordées à celui qu’ils choisissent, en général celui qui a le revenu le plus élevé, car la réduction ne peut pas dépasser l’impôt.`,
      h2b: 'Sans enfant',
      p2: `Un employé isolé sans enfant touche ${$(r.net)} net sur ce salaire, après ${$(r.onss)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale.`,
      faqs: [
        { q: 'Combien fait 4 000 € brut en net ?', a: `${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant. Avec deux enfants à charge, le net est de ${$(k2.net)}, et avec un conjoint sans revenus de ${$(cs.net)}. Le calcul inclut l’ONSS de 13,07 %, le précompte selon la formule-clé et la cotisation spéciale.` },
        { q: 'Combien rapporte un enfant à charge sur le salaire net ?', a: `Pour un enfant, la réduction annuelle est de ${$(P.pp.enfants[1], 0)}, soit ${$(P.pp.enfants[1] / 12)} de précompte en moins par mois. Pour deux enfants, ${$(P.pp.enfants[2], 0)} par an. Le montant augmente plus que proportionnellement avec le nombre d’enfants. Un enfant handicapé compte pour deux.` },
        { q: 'Qui reçoit la réduction si les deux parents travaillent ?', a: 'Le parent désigné par le couple, en le signalant à son employeur. Il est souvent préférable de la placer chez celui qui a le revenu le plus élevé, pour être sûr qu’elle soit entièrement utilisée. Dans la déclaration fiscale, la réduction est de toute façon recalculée au niveau du ménage.' },
      ] }) : ({ h1,
      title: `4 000 euro bruto netto 2026: vermindering voor kinderen`, description: `4 000 euro bruto geeft ${$(r.net)} netto in 2026 zonder kinderen, en ${$(k2.net)} met twee kinderen ten laste. Dit zijn de verminderingen voor kinderen.`,
      h2: 'Wat kinderen ten laste waard zijn',
      p: `De sleutelformule verlaagt de jaarbelasting met een vast bedrag volgens het aantal kinderen ten laste: ${$(P.pp.enfants[1], 0)} voor één kind, ${$(P.pp.enfants[2], 0)} voor twee, ${$(P.pp.enfants[3], 0)} voor drie en ${$(P.pp.enfants[4], 0)} voor vier. Een kind met een handicap telt dubbel. Bij een brutoloon van ${$(g, 0)} verlagen twee kinderen de voorheffing van ${$(r.pp)} naar ${$(k2.pp)} per maand, en stijgt het nettoloon van ${$(r.net)} naar ${$(k2.net)}. Een alleenstaande ouder krijgt bovendien ${$(P.pp.parent_isole, 0)} per jaar extra vermindering: zijn nettoloon wordt ${$(compute({ gross: g, children: 2, parentIsole: true }).net)}. Die verminderingen gelden per jaar en worden in de voorheffing door twaalf gedeeld. Werken beide ouders, dan krijgt de ouder die zij kiezen de vermindering, meestal degene met het hoogste inkomen, omdat de vermindering de belasting niet kan overschrijden. Kinderen hebben dus een grote invloed.`,
      h2b: 'Zonder kinderen',
      p2: `Een alleenstaande bediende zonder kinderen ontvangt bij dit loon ${$(r.net)} netto, na ${$(r.onss)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage.`,
      faqs: [
        { q: 'Hoeveel is 4 000 euro bruto netto?', a: `${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen. Met twee kinderen ten laste is het nettoloon ${$(k2.net)}, en met een partner zonder inkomen ${$(cs.net)}. De berekening omvat de RSZ van 13,07 %, de voorheffing volgens de sleutelformule en de bijzondere bijdrage.` },
        { q: 'Hoeveel levert een kind ten laste op in het nettoloon?', a: `Voor één kind bedraagt de jaarlijkse vermindering ${$(P.pp.enfants[1], 0)}, of ${$(P.pp.enfants[1] / 12)} minder voorheffing per maand. Voor twee kinderen ${$(P.pp.enfants[2], 0)} per jaar. Het bedrag stijgt meer dan evenredig met het aantal kinderen. Een kind met een handicap telt dubbel.` },
        { q: 'Wie krijgt de vermindering als beide ouders werken?', a: 'De ouder die het koppel aanwijst, door het aan zijn werkgever te melden. Het is vaak beter ze te leggen bij degene met het hoogste inkomen, zodat ze volledig benut wordt. In de belastingaangifte wordt de vermindering hoe dan ook opnieuw berekend op het niveau van het gezin.' },
      ] }),
    4500: () => lang === 'fr' ? ({ h1,
      title: `4 500 € brut en net 2026 : double pécule de vacances`, description: `4 500 € brut donnent ${$(r.net)} net par mois en 2026. Le double pécule de vacances de ${$(dp.amount)} brut laisse ${$(dp.net)} net, au taux spécial de ${pct(dp.rate, 2)}.`,
      h2: 'Le double pécule de vacances',
      p: `Chaque année, généralement en mai ou juin, un employé reçoit un double pécule de vacances égal à 92 % de son salaire mensuel brut. À ${$(g, 0)}, cela représente ${$(dp.amount)}. Une cotisation ONSS spéciale de 13,07 % est retenue sur 85/92 de ce montant, soit ${$(dp.onss)}. Le précompte n’est pas calculé comme sur un salaire ordinaire : il suit un taux fixe qui dépend de la rémunération annuelle normale. Pour ce salaire, le taux est de ${pct(dp.rate, 2)}, ce qui donne ${$(dp.pp)} de précompte. Le double pécule net est donc de ${$(dp.net)}. Ce taux élevé est une avance : l’impôt définitif est calculé dans la déclaration, où le pécule s’ajoute simplement aux autres revenus. Le simple pécule, lui, correspond au salaire normal payé pendant les jours de vacances.`,
      h2b: 'Le salaire mensuel',
      p2: `Hors pécule, le salaire mensuel net est de ${$(r.net)}, après ${$(r.onss)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale.`,
      faqs: [
        { q: 'Combien fait 4 500 € brut en net ?', a: `${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant. Avec deux enfants à charge, ${$(k2.net)}. Le double pécule de vacances, versé une fois par an, s’ajoute avec ${$(dp.net)} net pour ce salaire. Le simple pécule est payé comme un salaire ordinaire.` },
        { q: 'Comment est taxé le double pécule de vacances ?', a: `Il subit une cotisation ONSS de 13,07 % sur 85/92 de son montant et un précompte à taux fixe, déterminé par la rémunération annuelle normale. À ce niveau de salaire, le taux est de ${pct(dp.rate, 2)}. Le précompte retenu est ensuite régularisé dans la déclaration fiscale.` },
        { q: 'Les ouvriers reçoivent-ils aussi un double pécule ?', a: 'Oui, mais par une caisse de vacances et non par l’employeur. Leur pécule total vaut 15,38 % de la rémunération brute à 108 % de l’année précédente, et il est versé en une fois, généralement au printemps. Les règles de précompte sont différentes.' },
      ] }) : ({ h1,
      title: `4 500 euro bruto netto 2026: dubbel vakantiegeld`, description: `4 500 euro bruto geeft ${$(r.net)} netto per maand in 2026. Het dubbel vakantiegeld van ${$(dp.amount)} bruto laat ${$(dp.net)} netto over, tegen ${pct(dp.rate, 2)}.`,
      h2: 'Het dubbel vakantiegeld',
      p: `Elk jaar, meestal in mei of juni, ontvangt een bediende een dubbel vakantiegeld gelijk aan 92 % van zijn bruto maandloon. Bij ${$(g, 0)} is dat ${$(dp.amount)}. Op 85/92 van dat bedrag wordt een bijzondere RSZ-bijdrage van 13,07 % ingehouden, of ${$(dp.onss)}. De voorheffing wordt niet berekend zoals op een gewoon loon: ze volgt een vast percentage dat afhangt van het normale jaarloon. Voor dit loon bedraagt het percentage ${pct(dp.rate, 2)}, wat ${$(dp.pp)} voorheffing geeft. Het netto dubbel vakantiegeld bedraagt dus ${$(dp.net)}. Dat hoge percentage is een voorschot: de definitieve belasting wordt berekend in de aangifte, waar het vakantiegeld gewoon bij de andere inkomsten komt. Het enkel vakantiegeld is het normale loon dat tijdens de vakantiedagen wordt doorbetaald. Het wordt uitbetaald samen met het gewone loon.`,
      h2b: 'Het maandloon',
      p2: `Zonder vakantiegeld bedraagt het netto maandloon ${$(r.net)}, na ${$(r.onss)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage.`,
      faqs: [
        { q: 'Hoeveel is 4 500 euro bruto netto?', a: `${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen. Met twee kinderen ten laste ${$(k2.net)}. Het dubbel vakantiegeld, één keer per jaar uitbetaald, komt daarbovenop met ${$(dp.net)} netto voor dit loon. Het enkel vakantiegeld wordt als gewoon loon betaald.` },
        { q: 'Hoe wordt dubbel vakantiegeld belast?', a: `Er wordt 13,07 % RSZ ingehouden op 85/92 van het bedrag en een voorheffing tegen een vast percentage, bepaald door het normale jaarloon. Op dit loonniveau is dat ${pct(dp.rate, 2)}. De ingehouden voorheffing wordt daarna geregulariseerd in de belastingaangifte. Een deel komt vaak terug.` },
        { q: 'Krijgen arbeiders ook dubbel vakantiegeld?', a: 'Ja, maar via een vakantiekas en niet via de werkgever. Hun volledige vakantiegeld bedraagt 15,38 % van het brutoloon aan 108 % van het vorige jaar, en wordt in één keer uitbetaald, meestal in het voorjaar. De regels voor de voorheffing zijn anders.' },
      ] }),
    5000: () => lang === 'fr' ? ({ h1,
      title: `5 000 € brut en net 2026 : treizième mois et précompte`, description: `5 000 € brut donnent ${$(r.net)} net par mois en 2026. La prime de fin d’année d’un mois de salaire laisse ${$(yb.net)} net au taux de ${pct(yb.rate, 2)}.`,
      h2: 'Le treizième mois',
      p: `Dans de nombreuses commissions paritaires, dont la commission paritaire auxiliaire pour employés, les employés reçoivent en décembre une prime de fin d’année égale à un mois de salaire. Sur ${$(g, 0)} brut, l’ONSS de 13,07 % retire ${$(yb.onss)}, puis le précompte est calculé comme pour une allocation exceptionnelle, à un taux fixe qui dépend de la rémunération annuelle normale : ${pct(yb.rate, 2)} ici, soit ${$(yb.pp)}. La prime nette est de ${$(yb.net)}, à peine plus de la moitié du brut. Ce taux dépasse le taux marginal réel pour beaucoup de salariés, si bien qu’une partie revient souvent lors du décompte fiscal. Le salaire mensuel ordinaire, lui, donne ${$(r.net)} net. À ce niveau, la cotisation spéciale de sécurité sociale approche déjà de son plafond de ${$(P.csss.max_single)} par mois pour un isolé.`,
      h2b: 'Taux marginal',
      p2: `Sur 100 € brut supplémentaires, l’employé garde ${$(up.net - r.net)} net, soit un taux marginal de ${pct(marg)}, lié à la tranche de 48,15 % du barème du précompte.`,
      faqs: [
        { q: 'Combien fait 5 000 € brut en net ?', a: `${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant, après ${$(r.onss)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale. Avec un conjoint sans revenus, le net atteint ${$(cs.net)}. Le taux marginal est de ${pct(marg)}.` },
        { q: 'Combien reste-t-il d’un treizième mois de 5 000 € ?', a: `Environ ${$(yb.net)} net. L’ONSS retire ${$(yb.onss)} et le précompte, au taux exceptionnel de ${pct(yb.rate, 2)}, ${$(yb.pp)}. L’impôt définitif sur la prime est établi dans la déclaration, en même temps que sur le reste du salaire. Une partie revient souvent au décompte.` },
        { q: 'Tous les employés ont-ils droit à un treizième mois ?', a: 'Non, la prime de fin d’année dépend de la commission paritaire, du règlement de travail ou du contrat. Elle est très répandue, mais ses conditions varient : ancienneté minimale, calcul au prorata, montant parfois inférieur à un mois de salaire pour les ouvriers.' },
      ] }) : ({ h1,
      title: `5 000 euro bruto netto 2026: eindejaarspremie en voorheffing`, description: `5 000 euro bruto geeft ${$(r.net)} netto per maand in 2026. Een eindejaarspremie van één maandloon laat ${$(yb.net)} netto over tegen ${pct(yb.rate, 2)}.`,
      h2: 'De eindejaarspremie',
      p: `In veel paritaire comités, waaronder het aanvullend paritair comité voor bedienden, krijgen bedienden in december een eindejaarspremie gelijk aan één maandloon. Op ${$(g, 0)} bruto houdt de RSZ van 13,07 % ${$(yb.onss)} in, waarna de voorheffing wordt berekend zoals voor een uitzonderlijke vergoeding, tegen een vast percentage dat afhangt van het normale jaarloon: hier ${pct(yb.rate, 2)}, of ${$(yb.pp)}. De netto premie bedraagt ${$(yb.net)}, amper meer dan de helft van het brutobedrag. Dat percentage ligt voor veel werknemers boven hun werkelijke marginale tarief, waardoor een deel vaak terugkomt bij de belastingafrekening. Het gewone maandloon levert ${$(r.net)} netto op. Op dit niveau nadert de bijzondere bijdrage voor de sociale zekerheid al haar maximum van ${$(P.csss.max_single)} per maand voor een alleenstaande. Dat is een voorschot.`,
      h2b: 'Marginaal tarief',
      p2: `Van 100 euro bruto extra houdt de bediende ${$(up.net - r.net)} netto over, een marginaal tarief van ${pct(marg)}, door de schijf van 48,15 % van het voorheffingsbarema.`,
      faqs: [
        { q: 'Hoeveel is 5 000 euro bruto netto?', a: `${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen, na ${$(r.onss)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage. Met een partner zonder inkomen bedraagt het nettoloon ${$(cs.net)}. Het marginale tarief is ${pct(marg)}.` },
        { q: 'Hoeveel blijft er over van een eindejaarspremie van 5 000 euro?', a: `Ongeveer ${$(yb.net)} netto. De RSZ houdt ${$(yb.onss)} in en de voorheffing, tegen het uitzonderlijke percentage van ${pct(yb.rate, 2)}, ${$(yb.pp)}. De definitieve belasting op de premie wordt vastgesteld in de aangifte, samen met die op de rest van het loon.` },
        { q: 'Hebben alle bedienden recht op een eindejaarspremie?', a: 'Nee, de eindejaarspremie hangt af van het paritair comité, het arbeidsreglement of de arbeidsovereenkomst. Ze is wijdverspreid, maar de voorwaarden verschillen: minimale anciënniteit, pro-rataberekening, en voor arbeiders soms een bedrag lager dan een maandloon. Kijk dus naar je paritair comité.' },
      ] }),
    6000: () => lang === 'fr' ? ({ h1,
      title: `6 000 € brut en net 2026 : cotisation spéciale plafonnée`, description: `6 000 € brut donnent ${$(r.net)} net en 2026. La cotisation spéciale de sécurité sociale atteint son plafond de ${$(P.csss.max_single)} par mois pour un isolé.`,
      h2: 'Une cotisation spéciale au plafond',
      p: `La cotisation spéciale de sécurité sociale est retenue chaque mois selon un barème qui dépend du salaire brut et de la composition du ménage. Pour un isolé ou un ménage à un seul revenu, elle est plafonnée à ${$(P.csss.max_single)} par mois ; pour un ménage à deux revenus, à ${$(P.csss.max_two)}. À ${$(g, 0)} brut, le plafond est atteint : la cotisation n’augmente plus avec le salaire. Le reste du calcul donne ${$(r.onss)} d’ONSS et ${$(r.pp)} de précompte, pour un net de ${$(r.net)}. Le taux marginal est de ${pct(marg)} : sur 100 € brut supplémentaires, il reste ${$(up.net - r.net)} net. La retenue mensuelle est une avance ; la cotisation annuelle définitive est calculée par l’administration fiscale sur les revenus nets imposables du ménage et régularisée dans l’avertissement-extrait de rôle.`,
      h2b: 'Coût employeur',
      p2: `Ce salaire coûte ${$(ec.monthly)} par mois à l’employeur et environ ${$(ec.annual, 0)} par an avec treizième mois et double pécule.`,
      faqs: [
        { q: 'Combien fait 6 000 € brut en net ?', a: `${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant, après ${$(r.onss)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale. Avec deux enfants, ${$(k2.net)} ; avec un conjoint sans revenus, ${$(cs.net)}.` },
        { q: 'Quel est le maximum de la cotisation spéciale de sécurité sociale ?', a: `${$(P.csss.max_single)} par mois pour un isolé ou un ménage à un seul revenu, et ${$(P.csss.max_two)} pour un ménage où les deux conjoints ont des revenus. La cotisation annuelle définitive est calculée sur les revenus du ménage et peut différer des retenues.` },
        { q: 'Quel est le taux marginal à 6 000 € brut ?', a: `Environ ${pct(marg)}. Au-delà de la tranche de 48,15 %, le barème du précompte atteint 53,50 % pour la partie élevée du revenu, auquel s’ajoute l’ONSS de 13,07 % sur le brut. La cotisation spéciale, plafonnée, ne joue plus. Le net progresse donc lentement.` },
      ] }) : ({ h1,
      title: `6 000 euro bruto netto 2026: bijzondere bijdrage op maximum`, description: `6 000 euro bruto geeft ${$(r.net)} netto in 2026. De bijzondere bijdrage voor de sociale zekerheid bereikt haar maximum van ${$(P.csss.max_single)} per maand.`,
      h2: 'Een bijzondere bijdrage op haar maximum',
      p: `De bijzondere bijdrage voor de sociale zekerheid wordt elke maand ingehouden volgens een barema dat afhangt van het brutoloon en de gezinssamenstelling. Voor een alleenstaande of een gezin met één inkomen is ze begrensd op ${$(P.csss.max_single)} per maand; voor een gezin met twee inkomens op ${$(P.csss.max_two)}. Bij ${$(g, 0)} bruto is het maximum bereikt: de bijdrage stijgt niet meer met het loon. De rest van de berekening geeft ${$(r.onss)} RSZ en ${$(r.pp)} voorheffing, voor een nettoloon van ${$(r.net)}. Het marginale tarief bedraagt ${pct(marg)}: van 100 euro bruto extra blijft ${$(up.net - r.net)} netto over. De maandelijkse inhouding is een voorschot; de definitieve jaarlijkse bijdrage wordt door de fiscus berekend op het netto belastbaar inkomen van het gezin en geregulariseerd in het aanslagbiljet.`,
      h2b: 'Werkgeverskost',
      p2: `Dit loon kost de werkgever ${$(ec.monthly)} per maand en ongeveer ${$(ec.annual, 0)} per jaar met eindejaarspremie en dubbel vakantiegeld.`,
      faqs: [
        { q: 'Hoeveel is 6 000 euro bruto netto?', a: `${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen, na ${$(r.onss)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage. Met twee kinderen ${$(k2.net)}; met een partner zonder inkomen ${$(cs.net)}. De werkgeverskost bedraagt ${$(ec.monthly)}.` },
        { q: 'Wanneer bereikt de bijzondere bijdrage haar maximum?', a: `Voor een alleenstaande vanaf ongeveer ${$(P.csss.t2 + (P.csss.max_single - P.csss.base2) / P.csss.rate2, 0)} bruto per maand. ${$(P.csss.max_single)} per maand voor een alleenstaande of een gezin met één inkomen, en ${$(P.csss.max_two)} voor een gezin waarin beide partners een inkomen hebben. De definitieve jaarlijkse bijdrage wordt berekend op de inkomens van het gezin en kan afwijken van de inhoudingen.` },
        { q: 'Wat is het marginale tarief bij 6 000 euro bruto?', a: `Ongeveer ${pct(marg)}. Boven de schijf van 48,15 % bereikt het voorheffingsbarema 53,50 % voor het hoge deel van het inkomen, waarbij de RSZ van 13,07 % op het brutoloon komt. De begrensde bijzondere bijdrage speelt niet meer. Het nettoloon stijgt dus traag.` },
      ] }),
    7000: () => lang === 'fr' ? ({ h1,
      title: `7 000 € brut en net 2026 : tranche de 53,50 % et pension`, description: `7 000 € brut donnent ${$(r.net)} net en 2026. Le précompte atteint la tranche de 53,50 %, et une assurance de groupe réduit le précompte de 30 % des retenues.`,
      h2: 'La tranche la plus élevée',
      p: `À ${$(g, 0)} brut, une partie du revenu annuel net imposable dépasse ${$(P.pp.bareme[2].upto ?? 0, 0)} et est imposée dans la tranche de 53,50 % de la formule-clé, qui inclut déjà 7 % de taxe communale. Le précompte mensuel est de ${$(r.pp)}, l’ONSS de ${$(r.onss)}, la cotisation spéciale plafonnée à ${$(r.csss)}. Le net est de ${$(r.net)}, soit ${pct(r.net / g)} du brut. À ce niveau, beaucoup d’employeurs proposent une assurance de groupe avec une retenue personnelle. La formule-clé réduit alors le précompte de 30 % de cette retenue : avec ${$(100, 0)} de retenue par mois, le précompte baisse de ${$(30, 0)} et le net ne diminue que de ${$(70, 0)}. L’épargne-pension complémentaire est donc en partie financée par l’avantage fiscal. Le coût employeur atteint ${$(ec.monthly)} par mois, hors avantages extra-légaux comme la voiture de société.`,
      h2b: 'Taux marginal',
      p2: `Sur 100 € brut de plus, l’employé ne conserve que ${$(up.net - r.net)}, soit un taux marginal de ${pct(marg)}.`,
      faqs: [
        { q: 'Combien fait 7 000 € brut en net ?', a: `${$(r.net)} net par mois en 2026 pour un employé isolé sans enfant, après ${$(r.onss)} d’ONSS, ${$(r.pp)} de précompte et ${$(r.csss)} de cotisation spéciale. Avec un conjoint sans revenus, le net monte à ${$(cs.net)}. Le coût employeur atteint ${$(ec.monthly)}.` },
        { q: 'Quel est le taux maximal du précompte professionnel ?', a: 'Le barème de la formule-clé 2026 monte jusqu’à 53,50 % pour la partie du revenu annuel net imposable qui dépasse 51 050 €. Ce taux comprend une majoration forfaitaire de 7 % pour la taxe communale. Le taux réellement dû dépend ensuite de votre commune.' },
        { q: 'Une assurance de groupe réduit-elle le précompte ?', a: 'Oui. Les retenues personnelles obligatoires pour une assurance de groupe réduisent le précompte mensuel de 30 % de leur montant. Une retenue de 100 € ne diminue donc le net que d’environ 70 €. L’avantage est ensuite confirmé ou ajusté dans la déclaration fiscale.' },
      ] }) : ({ h1,
      title: `7 000 euro bruto netto 2026: schijf van 53,50 % en pensioen`, description: `7 000 euro bruto geeft ${$(r.net)} netto in 2026. De voorheffing bereikt de schijf van 53,50 %, en een groepsverzekering verlaagt de voorheffing met 30 %.`,
      h2: 'De hoogste schijf',
      p: `Bij ${$(g, 0)} bruto ligt een deel van het jaarlijks netto belastbaar inkomen boven ${$(P.pp.bareme[2].upto ?? 0, 0)} en wordt het belast in de schijf van 53,50 % van de sleutelformule, die al 7 % gemeentebelasting bevat. De maandelijkse voorheffing bedraagt ${$(r.pp)}, de RSZ ${$(r.onss)}, de bijzondere bijdrage is begrensd op ${$(r.csss)}. Het nettoloon bedraagt ${$(r.net)}, of ${pct(r.net / g)} van het brutoloon. Op dit niveau bieden veel werkgevers een groepsverzekering aan met een persoonlijke inhouding. De sleutelformule verlaagt de voorheffing dan met 30 % van die inhouding: bij ${$(100, 0)} inhouding per maand daalt de voorheffing met ${$(30, 0)} en het nettoloon maar met ${$(70, 0)}. Het aanvullend pensioensparen wordt zo deels door het belastingvoordeel gefinancierd. De werkgeverskost bedraagt ${$(ec.monthly)} per maand, zonder extralegale voordelen zoals een bedrijfswagen.`,
      h2b: 'Marginaal tarief',
      p2: `Van 100 euro bruto extra houdt de bediende maar ${$(up.net - r.net)} over, een marginaal tarief van ${pct(marg)}.`,
      faqs: [
        { q: 'Hoeveel is 7 000 euro bruto netto?', a: `${$(r.net)} netto per maand in 2026 voor een alleenstaande bediende zonder kinderen, na ${$(r.onss)} RSZ, ${$(r.pp)} voorheffing en ${$(r.csss)} bijzondere bijdrage. Met een partner zonder inkomen stijgt het nettoloon tot ${$(cs.net)}. De werkgeverskost bedraagt ${$(ec.monthly)}.` },
        { q: 'Wat is het hoogste tarief van de bedrijfsvoorheffing?', a: 'Het barema van de sleutelformule 2026 gaat tot 53,50 % voor het deel van het jaarlijks netto belastbaar inkomen boven 51 050 euro. Dat tarief bevat een forfaitaire verhoging van 7 % voor de gemeentebelasting. Het werkelijk verschuldigde tarief hangt daarna af van je gemeente.' },
        { q: 'Verlaagt een groepsverzekering de voorheffing?', a: 'Ja. De verplichte persoonlijke inhoudingen voor een groepsverzekering verlagen de maandelijkse voorheffing met 30 % van hun bedrag. Een inhouding van 100 euro verlaagt het nettoloon dus maar met ongeveer 70 euro. Het voordeel wordt daarna bevestigd of bijgesteld in de belastingaangifte.' },
      ] }),
  };
  return F[g]();
}
